		// Descriptor heap layout
		static const UINT HEAP_GBUFFER = 0;			// 5 SRVs, then 2 UAVs
		static const UINT HEAP_MESHES = 16;			// 2 per mesh (vertices, indices)
		static const UINT MAX_MESHES = 65536;
		static const UINT HEAP_TEXTURES = HEAP_MESHES + MAX_MESHES * 2;
		static const UINT MAX_TEXTURES = 8192;
		static const UINT HEAP_SIZE = HEAP_TEXTURES + MAX_TEXTURES;
		static const UINT NO_TEXTURE = 0xFFFFFFFF;

		enum Flags
		{
			FLAG_ALPHA_CUTOUT = 1,
			FLAG_INDIRECT = 2,
			FLAG_REFLECTIONS = 4,
			FLAG_SPECULAR = 8,
			FLAG_BOUNCE_LIGHTS = 16,
			FLAG_SHADOWS = 32,
			FLAG_TINTED_SHADOWS = 64
		};

		// Must match the cbuffer in RayTracer.hlsl
		struct alignas(16) Constants
		{
			float viewInv[16];
			float projInv[16];
			float camPos[4];
			float depth[4];		// near, far, normal buffer scale, gamma
			uint32_t size[4];	// width, height, sample index, flags
			uint32_t counts[4];	// lights, bounces, reflection bounces
			float sky[4];
			float ambient[4];
			float strengths[4];	// bounce light, emissive, reflection, roughness cutoff
			float ray[4];		// max distance, offset, sun softness (radians), light softness
			float misc[4];		// alpha threshold, specular strength, debug view
			float jitter[4];	// TAA jitter (normalized device coordinates)
			float color[4];		// bounce color saturation, glass tint strength, default emissive
			float pbr[4];		// normal map strength, normal maps enabled, texture AO strength
		};

		struct LightData
		{
			float posType[4];
			float dirSpecular[4];
			float colorStrength[4];
			float params[4];
			float params2[4];
		};

		struct InstanceData
		{
			uint32_t meshIndex;
			uint32_t texIndex;
			uint32_t flags;
			float emissive;
			float uvRect[4];
			float blendColor[4];
			float metallic;
			float roughness;
			uint32_t matTexIndex;
			uint32_t normalTexIndex;
			float matUvRect[4];
			float normalUvRect[4];
			uint32_t matFormat;
			uint32_t pad0, pad1, pad2;
		};

		struct MeshEntry
		{
			ID3D12Resource* vb = nullptr;
			ID3D12Resource* ib = nullptr;
			ID3D12Resource* blas = nullptr;
			uint32_t slot = 0;
		};

		struct TextureEntry
		{
			ID3D12Resource* tex = nullptr;
			uint32_t slot = NO_TEXTURE;
		};

		struct CapturedObject
		{
			Mesh<>* mesh;
			uint64_t meshUid;
			Matrix world;
			IntType texId;
			float uvRect[4];
			float blendColor[4];
			float metallic, roughness, emissive;
			BoolType castShadows;
			IntType matTexId, normalTexId;
			float matUvRect[4], normalUvRect[4];
			int32_t matFormat;
		};

		struct SharedTexture
		{
			ID3D12Resource* res12 = nullptr;
			ID3D11Texture2D* tex11 = nullptr;
			DXGI_FORMAT format = DXGI_FORMAT_UNKNOWN;
			UINT width = 0, height = 0;
		};

