		static BoolType initTried = false, supported = false;
		static QString status = "Not initialized";

		static ID3D12Device5* dev = nullptr;
		static ID3D12CommandQueue* queue = nullptr;
		static ID3D12CommandAllocator* allocator = nullptr;
		static ID3D12GraphicsCommandList4* list = nullptr;
		static ID3D12Fence* fence12 = nullptr;
		static ID3D11Fence* fence11 = nullptr;
		static ID3D11Device5* dev11 = nullptr;
		static ID3D11DeviceContext4* ctx11 = nullptr;
		static UINT64 fenceValue = 0, lastSubmitted = 0;
		static HANDLE fenceEvent = nullptr;

		static ID3D12RootSignature* rootSig = nullptr;
		static ID3D12PipelineState* pso = nullptr;
		static ID3D12DescriptorHeap* heap = nullptr;
		static UINT descSize = 0;

		static QHash<uint64_t, MeshEntry> meshes;
		static QVector<uint32_t> freeMeshSlots;
		static uint32_t nextMeshSlot = 0;
		static QHash<IntType, TextureEntry> textures;
		static uint32_t nextTexSlot = 0;

		static QVector<CapturedObject> captureList, sceneObjects;
		static BoolType captureCastShadows = true;
		static BoolType capturing = false, capturePaused = false, sceneDirty = false, sceneInvalid = true;
		static QSet<uint64_t> sceneMeshUids;

